import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden += 1
        elif tag in ('p', 'li', 'tr', 'h1', 'h2', 'h3', 'br') and not self.hidden:
            self.parts.append('\n')

    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.hidden:
            self.hidden -= 1
        elif tag in ('p', 'li', 'tr', 'h1', 'h2', 'h3') and not self.hidden:
            self.parts.append('\n')

    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(data)

root = Path('products/services/sqlite-lemon-squeezy-seller-fit')
sources = {
    'supported-countries': r'\bCanada\b|bank account|PayPal|payout',
    'fees': r'\$0\.50|\b5%|international|PayPal|subscription|payout|minimum',
}
result = {}
for name, pattern in sources.items():
    raw = (root / 'raw' / (name + '.html')).read_bytes()
    parser = VisibleText()
    parser.feed(raw.decode('utf-8'))
    lines = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines()]
    excerpts = []
    for line in lines:
        match = re.search(pattern, line, re.I)
        if match:
            excerpt = line[max(0, match.start() - 140):match.end() + 220]
            if excerpt not in excerpts:
                excerpts.append(excerpt)
    result[name] = {'url': 'https://docs.lemonsqueezy.com/help/getting-started/' + name, 'sha256': hashlib.sha256(raw).hexdigest(), 'matched_excerpt_count': len(excerpts), 'excerpts': excerpts[:30]}
result['scope'] = 'Public documentation excerpts for review. Seller approval, specific package eligibility, payout availability, and realized proceeds require separate evidence.'
output = root / 'director-country-fee-excerpts.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({name: result[name]['matched_excerpt_count'] for name in sources}))
